/**
 * Petshop Katalogo Rikiavimas v1.0 (isparduotos prekes i gala)
 *
 * Floats out-of-stock products to the end of shop / product-category /
 * product-tag archive listings, AFTER the active sort order
 * (price, popularity, date, etc). Out-of-stock products stay visible
 * (demand asset + SEO, S98) - they are only pushed to the bottom.
 *
 * Uses wc_product_meta_lookup (indexed stock_status column),
 * not a postmeta JOIN. Front-end main product query only.
 *
 * [VISADA AKTYVUS]
 */

if (!defined('ABSPATH')) {
    return;
}

add_filter('posts_clauses', 'petshop_oos_last_clauses', 20, 2);
function petshop_oos_last_clauses($clauses, $query) {

    // Front-end main query only.
    if (is_admin() || !$query->is_main_query()) {
        return $clauses;
    }

    // Canonical WooCommerce flag for the shop / taxonomy product loop.
    if ($query->get('wc_query') !== 'product_query') {
        return $clauses;
    }

    global $wpdb;

    $lookup = $wpdb->prefix . 'wc_product_meta_lookup';

    // Avoid a duplicate join if something already joined our alias.
    if (strpos($clauses['join'], 'petshop_oos_lookup') === false) {
        $clauses['join'] .= " LEFT JOIN {$lookup} AS petshop_oos_lookup"
            . " ON ({$wpdb->posts}.ID = petshop_oos_lookup.product_id) ";
    }

    // 1 = out of stock (sorts last), 0 = in stock / backorder (sorts first).
    // Existing orderby is kept AFTER it, so the chosen sort still applies
    // inside each group.
    $oos_order = "(petshop_oos_lookup.stock_status = 'outofstock') ASC";

    if (!empty($clauses['orderby'])) {
        $clauses['orderby'] = $oos_order . ", " . $clauses['orderby'];
    } else {
        $clauses['orderby'] = $oos_order;
    }

    return $clauses;
}
